--
DELIMITER $$
CREATE TRIGGER `trg_update_asset_value` AFTER INSERT ON `asset_depreciation_schedule` FOR EACH ROW BEGIN
    UPDATE fixed_assets
    SET accumulated_depreciation = accumulated_depreciation + NEW.depreciation_amount,
        current_value = purchase_cost - (accumulated_depreciation + NEW.depreciation_amount),
        updated_at = NOW()
    WHERE id = NEW.asset_id;
END
$$
DELIMITER ;

