--
-- Table structure for table `disbursements`
--

CREATE TABLE `disbursements` (
  `id` int(11) NOT NULL,
  `disbursement_number` varchar(20) NOT NULL,
  `disbursement_date` date NOT NULL,
  `payee_type` enum('employee','vendor','other') DEFAULT NULL,
  `payee_name` varchar(255) DEFAULT NULL,
  `payee` varchar(100) DEFAULT NULL,
  `amount` decimal(15,2) NOT NULL,
  `payment_method` enum('cash','check','bank_transfer','other') NOT NULL,
  `reference_number` varchar(100) DEFAULT NULL,
  `bank_account_id` int(11) DEFAULT NULL,
  `purpose` text NOT NULL,
  `department` varchar(100) DEFAULT NULL,
  `account_id` int(11) DEFAULT NULL,
  `approved_by` int(11) DEFAULT NULL,
  `recorded_by` int(11) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `status` enum('pending','approved','paid','cancelled') DEFAULT 'pending',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `needs_approval` tinyint(1) DEFAULT 0,
  `approval_id` int(11) DEFAULT NULL,
  `approval_status` enum('not_required','pending','approved','rejected') DEFAULT 'not_required'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci;

--
-- Dumping data for table `disbursements`
--


--
-- Triggers `disbursements`
--
DELIMITER $$
CREATE TRIGGER `bi_disbursements_sync` BEFORE INSERT ON `disbursements` FOR EACH ROW BEGIN
  -- Map payee_name into payee if payee not provided
  IF NEW.payee IS NULL AND NEW.payee_name IS NOT NULL THEN
    SET NEW.payee = LEFT(NEW.payee_name, 100);
  END IF;

  -- Map created_by -> recorded_by
  IF NEW.recorded_by IS NULL AND NEW.created_by IS NOT NULL THEN
    SET NEW.recorded_by = NEW.created_by;
  END IF;

  -- If account_id is missing, try defaulting to 6400 (common expense acct)
  IF NEW.account_id IS NULL THEN
    -- Only set if chart_of_accounts has id=6400
    IF EXISTS (SELECT 1 FROM chart_of_accounts WHERE id = 6400) THEN
      SET NEW.account_id = 6400;
    END IF;
  END IF;
END
$$
DELIMITER ;

