--
-- Triggers `payments_received`
--
DELIMITER $$
CREATE TRIGGER `bi_payments_received_sync` BEFORE INSERT ON `payments_received` FOR EACH ROW BEGIN
  -- amount: if dummy uses amount_paid, copy to amount
  IF (NEW.amount IS NULL OR NEW.amount = 0) AND NEW.amount_paid IS NOT NULL THEN
    SET NEW.amount = NEW.amount_paid;
  END IF;

  -- reference number: copy reference_no to reference_number
  IF NEW.reference_number IS NULL AND NEW.reference_no IS NOT NULL THEN
    SET NEW.reference_number = NEW.reference_no;
  END IF;

  -- recorded_by: copy created_by to recorded_by
  IF NEW.recorded_by IS NULL AND NEW.created_by IS NOT NULL THEN
    SET NEW.recorded_by = NEW.created_by;
  END IF;

  -- default updated_at
  IF NEW.updated_at IS NULL THEN
    SET NEW.updated_at = CURRENT_TIMESTAMP;
  END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_update_bank_balance_payment_received` AFTER INSERT ON `payments_received` FOR EACH ROW BEGIN
    IF NEW.bank_account_id IS NOT NULL THEN
        UPDATE bank_accounts
        SET current_balance = current_balance + NEW.amount,
            updated_at = NOW()
        WHERE id = NEW.bank_account_id;
    END IF;
END
$$
DELIMITER ;

