(1, 'invoice_overdue', 'Invoice Overdue Notice', 'Payment Overdue for Invoice {invoice_number}', '<p>Dear {customer_name},</p><p>Your invoice {invoice_number} for {total_amount} is now overdue. Please arrange payment immediately.</p><p>Best regards,<br>ATIERA Finance Team</p>', 'Dear {customer_name},\n\nYour invoice {invoice_number} for {total_amount} is now overdue. Please arrange payment immediately.\n\nBest regards,\nATIERA Finance Team', '[\"customer_name\",\"invoice_number\",\"total_amount\",\"due_date\"]', 1, NULL, '2026-01-09 08:03:54', '2026-01-09 08:03:54'),
(2, 'payment_reminder', 'Payment Reminder', 'Payment Reminder for Invoice {invoice_number}', '<p>Dear {customer_name},</p><p>This is a friendly reminder that payment for invoice {invoice_number} is due on {due_date}.</p><p>Best regards,<br>ATIERA Finance Team</p>', 'Dear {customer_name},\n\nThis is a friendly reminder that payment for invoice {invoice_number} is due on {due_date}.\n\nBest regards,\nATIERA Finance Team', '[\"customer_name\",\"invoice_number\",\"due_date\",\"total_amount\"]', 1, NULL, '2026-01-09 08:03:54', '2026-01-09 08:03:54'),
(3, 'welcome_user', 'Welcome New User', 'Welcome to ATIERA Finance', '<p>Dear {user_name},</p><p>Welcome to ATIERA Financial Management System. Your account has been created successfully.</p><p>Username: {username}</p><p>Best regards,<br>ATIERA Team</p>', 'Dear {user_name},\n\nWelcome to ATIERA Financial Management System. Your account has been created successfully.\n\nUsername: {username}\n\nBest regards,\nATIERA Team', '[\"user_name\",\"username\",\"login_url\"]', 1, NULL, '2026-01-09 08:03:54', '2026-01-09 08:03:54');
