(1, 'Invoice Approval Workflow', 'Multi-step approval process for invoices over threshold', '{\r\n  \"trigger\": \"invoice.created\",\r\n  \"conditions\": [{\"field\": \"total_amount\", \"operator\": \">\", \"value\": 50000}],\r\n  \"steps\": [\r\n    {\r\n      \"name\": \"Manager Approval\",\r\n      \"type\": \"approval\",\r\n      \"assignee_role\": \"admin\",\r\n      \"timeout_hours\": 24,\r\n      \"actions\": {\r\n        \"approve\": {\"status\": \"approved\", \"notification\": \"Invoice approved by manager\"},\r\n        \"reject\": {\"status\": \"rejected\", \"notification\": \"Invoice rejected by manager\"}\r\n      }\r\n    },\r\n    {\r\n      \"name\": \"Finance Review\",\r\n      \"type\": \"approval\",\r\n      \"assignee_role\": \"finance\",\r\n      \"timeout_hours\": 48,\r\n      \"actions\": {\r\n        \"approve\": {\"status\": \"approved\", \"notification\": \"Invoice approved by finance\"},\r\n        \"reject\": {\"status\": \"rejected\", \"notification\": \"Invoice rejected by finance\"}\r\n      }\r\n    }\r\n  ]\r\n}', 1, 1, '2025-10-24 16:54:47', '2026-01-18 04:32:58'),
(2, 'Bill Payment Workflow', 'Automated bill payment processing', '{\r\n  \"trigger\": \"bill.approved\",\r\n  \"conditions\": [],\r\n  \"steps\": [\r\n    {\r\n      \"name\": \"Schedule Payment\",\r\n      \"type\": \"action\",\r\n      \"action\": \"schedule_payment\",\r\n      \"delay_days\": 0,\r\n      \"conditions\": [{\"field\": \"payment_terms\", \"operator\": \"==\", \"value\": \"Net 30\"}]\r\n    },\r\n    {\r\n      \"name\": \"Payment Reminder\",\r\n      \"type\": \"notification\",\r\n      \"template\": \"payment_reminder\",\r\n      \"delay_days\": 25,\r\n      \"recipients\": [\"finance_team\"]\r\n    }\r\n  ]\r\n}', 1, 1, '2025-10-24 16:54:47', '2025-10-24 16:54:47'),
(3, 'Overdue Invoice Management', 'Automated handling of overdue invoices', '{\r\n  \"trigger\": \"invoice.overdue\",\r\n  \"conditions\": [],\r\n  \"steps\": [\r\n    {\r\n      \"name\": \"Send Overdue Notice\",\r\n      \"type\": \"notification\",\r\n      \"template\": \"overdue_notice\",\r\n      \"recipients\": [\"customer\"]\r\n    },\r\n    {\r\n      \"name\": \"Escalate to Collections\",\r\n      \"type\": \"action\",\r\n      \"action\": \"create_task\",\r\n      \"delay_days\": 7,\r\n      \"assignee_role\": \"collections\",\r\n      \"task_title\": \"Follow up on overdue invoice\",\r\n      \"task_priority\": \"high\"\r\n    }\r\n  ]\r\n}', 1, 1, '2025-10-24 16:54:47', '2025-10-24 16:54:47');
